const STRATEGIES = ['neighbour', 'bm25', 'bm25+graph', 'map+graph'] as const;
const MAP_SHARE = 0.3;
const W = 640;
const H = 300;
const PAD = {top: 16, right: 110, bottom: 36, left: 44};

type Packed = {used: number; seen: Set<number>; body: Set<number>; order: {idx: number; sig: boolean; cost: number}[]};

export function pack(task: Task, strategy: string, budget: number): Packed {
  let used = 0;
  let sigUsed = 0;
  const seen = new Set<number>();
  const body = new Set<number>();
  const order: Packed['order'] = [];
  for (const item of task.rank[strategy]) {
    const sig = item < 0;
    const idx = sig ? -item - 1 : item;
    const cost = sig ? DATA.chunks[idx][3] : DATA.chunks[idx][2];
    if (used + cost > budget || (sig && sigUsed + cost > MAP_SHARE * budget)) continue;
    used += cost;
    seen.add(idx);
    if (sig) sigUsed += cost;
    else body.add(idx);
    order.push({idx, sig, cost});
  }
  return {used, seen, body, order};
}

export function recall(strategy: string, budget: number, tasks: Task[] = DATA.tasks) {
  let sig = 0;
  let body = 0;
  for (const t of tasks) {
    const p = pack(t, strategy, budget);
    sig += t.needed.filter((n) => p.seen.has(n)).length / t.needed.length;
    body += t.needed.filter((n) => p.body.has(n)).length / t.needed.length;
  }
  return {sig: sig / tasks.length, body: body / tasks.length};
}

const BUDGET_STEPS = Array.from({length: 16}, (_, i) => 250 * (i + 1));

export default function AssistantContextLab() {
  const dark = useDarkViz();
  const [strategy, setStrategy] = useState<string>('bm25+graph');
  const [budget, setBudget] = useState(1000);
  const [task, setTask] = useState(-1);

  const curves = useMemo(
    () => STRATEGIES.map((st) => BUDGET_STEPS.map((b) => recall(st, b).body)),
    [],
  );
  const now = recall(strategy, budget, task < 0 ? DATA.tasks : [DATA.tasks[task]]);

  const colours = STRATEGIES.map((_, i) => seriesColor(i, dark));
  const neutral = dark ? '#848c99' : '#9aa0a6';
  const innerW = W - PAD.left - PAD.right;
  const innerH = H - PAD.top - PAD.bottom;
  const px = (b: number) => PAD.left + ((b - 250) / (4000 - 250)) * innerW;
  const py = (v: number) => PAD.top + innerH - v * innerH;

  const rows: (string | number)[][] = [];
  for (const st of STRATEGIES) {
    for (const b of DATA.budgets) {
      const r = recall(st, b);
      rows.push([st, b, r.sig.toFixed(3), r.body.toFixed(3)]);
    }
  }

  const single = task >= 0 ? DATA.tasks[task] : null;
  const packed = single ? pack(single, strategy, budget) : null;
  const barX = 20;
  const barW = W - 40;
  let cursor = barX;

  const status = single
    ? `${DATA.chunks[single.own][0]}: signature recall ${now.sig.toFixed(3)}, body recall ${now.body.toFixed(3)}`
    : `${strategy} at ${budget} tokens over all 30 tasks: signature recall ${now.sig.toFixed(3)}, body recall ${now.body.toFixed(3)}`;

  return (
    <VizPanel
      title="Packing code context under a token budget"
      hint="Thirty completion points from one real repository. Raise the budget and watch body recall: graph expansion beats plain keyword search, and a signature map buys cheap recall of signatures but not of bodies. The default, bm25+graph at 1,000 tokens, gives 0.500 and 0.500, the figures the chapter prints."
      legend={
        single
          ? [
              {label: 'needed definition', color: colours[0]},
              {label: 'signature only', color: colours[3]},
              {label: 'other context', color: neutral},
            ]
          : STRATEGIES.map((st, i) => ({label: st, color: colours[i]}))
      }
      table={{columns: ['strategy', 'budget', 'signature recall', 'body recall'], rows}}
      controls={
        <>
          <label className={s.control}>
            strategy
            <select className={s.select} value={strategy} onChange={(e) => setStrategy(e.target.value)}>
              {STRATEGIES.map((st) => (
                <option key={st} value={st}>
                  {st}
                </option>
              ))}
            </select>
          </label>
          <label className={s.control}>
            budget
            <input
              type="range"
              min={250}
              max={4000}
              step={250}
              value={budget}
              onChange={(e) => setBudget(Number(e.target.value))}
            />
            <span className={s.value}>{budget}</span>
          </label>
          <label className={s.control}>
            task
            <select className={s.select} value={task} onChange={(e) => setTask(Number(e.target.value))}>
              <option value={-1}>all 30 tasks, average</option>
              {DATA.tasks.map((t, i) => (
                <option key={i} value={i}>
                  {i + 1}. {DATA.chunks[t.own][0]}
                </option>
              ))}
            </select>
          </label>
          <span className={s.value} aria-live="polite">
            {status}
          </span>
        </>
      }>
      {!single && (
        <svg className={s.svg} viewBox={`0 0 ${W} ${H}`} role="img" aria-label="Body recall against token budget for four context strategies">
          <line className={s.axis} x1={PAD.left} y1={py(0)} x2={PAD.left + innerW} y2={py(0)} />
          <line className={s.axis} x1={PAD.left} y1={py(0)} x2={PAD.left} y2={py(1)} />
          {[0, 0.25, 0.5, 0.75, 1].map((v) => (
            <g key={v}>
              <line className={s.grid} x1={PAD.left} y1={py(v)} x2={PAD.left + innerW} y2={py(v)} />
              <text className={s.tick} x={PAD.left - 6} y={py(v) + 3} textAnchor="end">
                {v}
              </text>
            </g>
          ))}
          {[250, 1000, 2000, 3000, 4000].map((b) => (
            <text key={b} className={s.tick} x={px(b)} y={H - 18} textAnchor="middle">
              {b}
            </text>
          ))}
          <text className={s.axisLabel} x={PAD.left + innerW / 2} y={H - 4} textAnchor="middle">
            context budget in tokens
          </text>
          <text className={s.axisLabel} x={12} y={PAD.top + innerH / 2} textAnchor="middle" transform={`rotate(-90 12 ${PAD.top + innerH / 2})`}>
            body recall
          </text>
          <line x1={px(budget)} y1={py(0)} x2={px(budget)} y2={py(1)} stroke="var(--text-faint)" strokeDasharray="3 3" />
          {STRATEGIES.map((st, i) => (
            <g key={st}>
              <path
                d={curves[i].map((v, j) => `${j ? 'L' : 'M'}${px(BUDGET_STEPS[j]).toFixed(1)},${py(v).toFixed(1)}`).join(' ')}
                fill="none"
                stroke={colours[i]}
                strokeWidth={st === strategy ? 3.2 : 1.8}
                strokeDasharray={st === 'neighbour' ? '5 3' : undefined}
              />
              <text className={s.dataLabel} x={px(4000) + 6} y={py(curves[i][curves[i].length - 1]) + 3} fill={colours[i]}>
                {st}
              </text>
            </g>
          ))}
        </svg>
      )}
      {single && packed && (
        <svg className={s.svg} viewBox={`0 0 ${W} ${H}`} role="img" aria-label="Budget bar filled with packed context items">
          <text className={s.axisLabel} x={barX} y={26}>
            {DATA.chunks[single.own][1]} / {DATA.chunks[single.own][0]}
          </text>
          <rect x={barX} y={40} width={barW} height={34} fill="none" stroke="var(--border-strong)" />
          {packed.order.map((o, i) => {
            const w = (o.cost / budget) * barW;
            const x = cursor;
            cursor += w;
            const needed = single.needed.includes(o.idx);
            const fill = o.sig ? colours[3] : needed ? colours[0] : neutral;
            return <rect key={i} x={x} y={41} width={Math.max(w - 1, 0.5)} height={32} fill={fill} opacity={needed || o.sig ? 0.95 : 0.55} />;
          })}
          <text className={s.tick} x={barX} y={92}>
            0
          </text>
          <text className={s.tick} x={barX + barW} y={92} textAnchor="end">
            {packed.used} of {budget} tokens used, {packed.order.length} items
          </text>
          <text className={s.axisLabel} x={barX} y={128}>
            definitions the completion needs
          </text>
          {single.needed.map((n, i) => {
            const status = packed.body.has(n) ? 'body in context' : packed.seen.has(n) ? 'signature only' : 'missing';
            const colour = packed.body.has(n) ? colours[2] : packed.seen.has(n) ? colours[3] : (dark ? DIVERGING.dark.negative : DIVERGING.light.negative);
            return (
              <g key={n}>
                <rect x={barX} y={142 + i * 34} width={10} height={10} fill={colour} />
                <text className={s.dataLabel} x={barX + 18} y={151 + i * 34}>
                  {DATA.chunks[n][1]} / {DATA.chunks[n][0]} ({DATA.chunks[n][2]} tokens): {status}
                </text>
              </g>
            );
          })}
        </svg>
      )}
    </VizPanel>
  );
}
